@lru_cache(maxsize=10_000)
def _customer(customer_id: str) -> Customer:      # cached resource lookup
    return repo.find(customer_id) or Customer.unknown(customer_id)

def enrich(order: Order) -> Order:
    c = _customer(order.customer_id)
    return order.model_copy(update={"customer_name": c.name, "region": c.region})
